namespace sv_853a07a49f34420f857c83b3a3e03e26.Services;

public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-1";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            OnChange?.Invoke();
        }
    }

    public event Action? OnChange;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-1", "Warehouse A — Downtown"),
        ("WH-2", "Warehouse B — Airport"),
        ("WH-3", "Warehouse C — Harbor"),
    ];

    public void Dispose() => OnChange = null;
}

namespace sv_853a07a49f34420f857c83b3a3e03e26.Services;

public sealed class InventoryAlertService : IDisposable
{
    private static readonly Random _rng = Random.Shared;

    public int LastKnownCount { get; private set; }

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _rng.Next(0, 16);
        LastKnownCount = count;
        return Task.FromResult(count);
    }

    /// <summary>
    /// Raised after a poll completes so every subscriber can re-render.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public void NotifyCountChanged() => OnAlertCountChanged?.Invoke();

    public void Dispose() => OnAlertCountChanged = null;
}

@using sv_853a07a49f34420f857c83b3a3e03e26.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label text-white mb-1 small">Current Warehouse</label>
    <select class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "WH-1";
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@using sv_853a07a49f34420f857c83b3a3e03e26.Services
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.LastKnownCount > 0)
{
    <span class="badge rounded-pill @BadgeClass">@AlertService.LastKnownCount</span>
}
else
{
    <span class="badge rounded-pill bg-success">0</span>
}

@code {
    [Parameter] public bool Large { get; set; }

    private string BadgeClass => AlertService.LastKnownCount >= 10 ? "bg-danger" : "bg-warning text-dark";

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnCountChanged;
    }

    private void OnCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnCountChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer

@using sv_853a07a49f34420f857c83b3a3e03e26.Services
@using sv_853a07a49f34420f857c83b3a3e03e26.Components.Layout
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            @WarehouseStateService.AvailableWarehouses
                .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        </h5>
        <p class="card-text">
            Warehouse ID: <code>@WarehouseState.CurrentWarehouseId</code>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body d-flex align-items-center gap-3">
        <h5 class="card-title mb-0">Low-Stock Alerts</h5>
        <AlertBadge Large="true" />
    </div>
    <div class="card-footer text-muted small">
        Polling every 10 seconds &bull; Last update: @_lastPoll?.ToString("HH:mm:ss")
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private DateTime? _lastPoll;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await PollOnceAsync();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await PollOnceAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollOnceAsync()
    {
        await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _lastPoll = DateTime.Now;

        // Notify ALL subscribers (sidebar badge, this page, etc.)
        AlertService.NotifyCountChanged();
        await InvokeAsync(StateHasChanged);
    }

    private async void OnWarehouseChanged()
    {
        // Immediately re-poll when warehouse changes
        await PollOnceAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
    }
}

