    private CancellationTokenSource? _cts;
    private DateTime? _lastPoll;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await PollOnceAsync();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await PollOnceAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollOnceAsync()
    {
        await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _lastPoll = DateTime.Now;

        // Notify ALL subscribers (sidebar badge, this page, etc.)
        AlertService.NotifyCountChanged();
        await InvokeAsync(StateHasChanged);
    }

    private async void OnWarehouseChanged()
    {
        // Immediately re-poll when warehouse changes
        await PollOnceAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
    }
}

